// Reviso lo minimo que necesita un asesor para atender el pedido.
// n8n pone el JSON del webhook dentro de body, por eso primero lo saco de ahi.
let order = $json.body ?? $json;

if (typeof order === 'string') {
  try {
    order = JSON.parse(order);
  } catch (error) {
    order = {};
  }
}

const required = ['full_name', 'email', 'phone', 'consent'];
const missing = required.filter((field) => !order[field]);
const hasItems = Array.isArray(order.items) && order.items.length > 0;

if (!hasItems) {
  missing.push('items');
}

return [{
  json: {
    ...order,
    is_valid: missing.length === 0,
    validation_status: missing.length === 0 ? 'valid' : 'invalid',
    missing_fields: missing,
    received_at: new Date().toISOString(),
  }
}];

// Dejo la fila lista para Google Sheets.
// Todavia no escribo en Sheets porque falta conectar credenciales de Google.
const lead = $json.lead ?? {};
const sheetRow = $json.sheet_row ?? lead.sheet_row ?? {};

return [{
  json: {
    ...$json,
    sheet_row: sheetRow,
    sheet_status: 'ready_for_google_sheets',
  }
}];

// Preparo el aviso para el asesor, pero mantengo todos los datos del lead.
const lead = $json.lead ?? {};
const message = $json.advisor_message ?? lead.advisor_message ?? `Nuevo lead prioritario: ${lead.full_name ?? 'cliente por revisar'}`;

return [{
  json: {
    ...$json,
    advisor_message: message,
    notification_payload: {
      lead,
      quote: $json.quote,
      advisor_message: message,
      channel: 'advisor_inbox',
    },
  }
}];
